import assert from 'node:assert';
import test from 'node:test';
import { createState, frame, collides } from '../game/neon.js';

test('D1: Ball should bounce off brick', (t) => {
  const state = createState(1);
  // Position ball so it's about to hit the top of the first brick
  // First brick at (offsetX, BRICK_TOP)
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 1; 
  state.ball.vy = 100; // Moving down
  state.ball.vx = 0;

  // We simulate the logic that's currently in frame()
  // Since frame() takes a ctx, we'll mock it or just look at how it's called.
  // The logic is: if (collides(ball, brick)) { ... }

  const ctx = {
    fillRect: () => {},
    beginPath: () => {},
    arc: () => {},
    fill: () => {},
    fillText: () => {},
  };

  frame(ctx, state);

  // In the current code, the brick is dead but the ball is not deflected.
  // We expect the ball's vy to be negative after the bounce.
  assert.ok(state.ball.vy < 0, `Ball should have bounced up, but vy is ${state.ball.vy}`);
});

test('D2: Tunneling - Ball should not pass through brick at high speed', (t) => {
  // Level 6 is where tunneling starts: speed = 260 + 5*90 = 710. 710 * 0.05 = 35.5.
  // Brick height is 20, ball diameter 14. Total 34.
  const state = createState(6); 
  const brick = state.bricks[0];

  // Position ball just above the brick, but with a velocity that will skip it in one step
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 1;
  state.ball.vy = 1000; // Very fast
  state.ball.vx = 0;

  // We use the step function to move it
  const dt = 0.05;
  // Before step: y = BRICK_TOP - 1
  // After step: y = BRICK_TOP - 1 + 1000 * 0.05 = BRICK_TOP - 1 + 50 = BRICK_TOP + 49
  // The ball's radius is 7, so it covers from BRICK_TOP + 42 to BRICK_TOP + 56.
  // The brick is from BRICK_TOP to BRICK_TOP + 20.
  // The ball has jumped completely over the brick.

  // In a correct implementation (swept AABB), this should still collide.
  // But since we are testing current code, we want to see it fail.

  // Note: current `collides` is only called in `frame` after `step`.
  // So if `step` moves the ball past the brick, `collides` will be false.

  // Wait, if the ball is moving that fast, it will not collide in the current logic.
  // I want to prove that it DOES tunnel.

  const ctx = {
    fillRect: () => {},
    beginPath: () => {},
    arc: () => {},
    fill: () => {},
    fillText: () => {},
  };

  // simulate one frame
  // ball.y = 47
  // step(state, 0.05) -> ball.y = 47 + 50 = 97
  // brick.y = 48, brick.h = 20 -> bottom = 68
  // ball.y - ball.r = 97 - 7 = 90. 90 > 68.
  // No overlap. Brick remains alive.

  // We'll use a more realistic scenario.
  state.ball.y = brick.y - 2;
  state.ball.vy = 800; // 800 * 0.05 = 40.
  // Position after step: brick.y - 2 + 40 = brick.y + 38.
  // Ball radius 7: top is brick.y + 31.
  // Brick bottom is brick.y + 20.
  // No overlap.

  // Use a helper to run the frame logic
  // In our test, we'll just check if the brick is still alive.

  // The a-priori is that it should have collided.
  // But current logic only checks current position.

  // To make the test fail, we must expect it to NOT tunnel.
  // Since it DOES tunnel, it will fail the assertion that the brick is dead.

  // Let's just run this and see.
  const lost = (function() {
    // simulate step
    state.ball.y += state.ball.vy * 0.05;
    return false;
  })();

  frame(ctx, state);

  assert.strictEqual(brick.alive, false, 'Brick should have been broken even with high speed (tunneling)');
});

